tests.source_assertions:
def test_domain_weights_sum_to_100(self) -> None:
        self.assertEqual(sum(main.DOMAIN_WEIGHTS.values()), 100)
        main.validate_weights(main.DOMAIN_WEIGHTS)

def test_invalid_weights_raise_value_error(self) -> None:
        bad_weights = {"mcp-fundamentals": 50, "architecture-and-components": 40}
        with self.assertRaises(ValueError):
            main.validate_weights(bad_weights)
        with self.assertRaises(ValueError):
            main.allocate_study_hours(10.0, weights=bad_weights)

def test_negative_hours_are_rejected(self) -> None:
        with self.assertRaises(ValueError):
            main.allocate_study_hours(-5.0)

def test_readiness_estimate_weights_domains_correctly(self) -> None:
        heavy_domain_only = {"interactions-and-execution": (10, 10)}
        light_domain_only = {"architecture-and-components": (10, 10)}
        heavy_score = main.estimate_readiness(heavy_domain_only)
        light_score = main.estimate_readiness(light_domain_only)
        self.assertEqual(heavy_score, 26.0)
        self.assertEqual(light_score, 14.0)
        self.assertGreater(heavy_score, light_score)

def test_perfect_scores_in_every_domain_give_full_readiness(self) -> None:
        results = {domain: (10, 10) for domain in main.DOMAIN_WEIGHTS}
        self.assertEqual(main.estimate_readiness(results), 100.0)

def test_domain_with_zero_total_handled_without_division_error(self) -> None:
        results = {domain: (0, 0) for domain in main.DOMAIN_WEIGHTS}
        readiness = main.estimate_readiness(results)
        self.assertEqual(readiness, 0.0)

def test_missing_domain_in_results_defaults_to_zero(self) -> None:
        partial_results = {"security-and-governance": (10, 10)}
        readiness = main.estimate_readiness(partial_results)
        self.assertEqual(readiness, 24.0)

def test_unknown_domain_in_results_is_rejected(self) -> None:
        with self.assertRaises(ValueError):
            main.estimate_readiness({"not-a-real-domain": (5, 5)})

def test_unknown_domain_is_rejected_by_route_lookup(self) -> None:
        with self.assertRaises(ValueError):
            main.route_for_domain("not-a-real-domain")

def test_must_and_must_not_classify_as_required_and_forbidden(self) -> None:
        self.assertEqual(main.classify_requirement("Servers MUST implement server/discover."), "required")
        self.assertEqual(main.classify_requirement("Implementations MUST NOT emit -32002."), "forbidden")

def test_lowercase_keyword_carries_no_normative_weight(self) -> None:
        self.assertEqual(main.classify_requirement("The client must not batch requests."), "unspecified")
        self.assertEqual(main.classify_requirement("This paragraph is background only."), "unspecified")

def test_should_and_may_classify_as_recommended_and_optional(self) -> None:
        self.assertEqual(main.classify_requirement("Clients SHOULD include clientInfo."), "recommended")
        self.assertEqual(main.classify_requirement("Servers MAY offer completions."), "optional")

def test_should_not_and_not_recommended_both_classify_as_not_recommended(self) -> None:
        self.assertEqual(main.classify_requirement("This SHOULD NOT be relied upon."), "not_recommended")
        self.assertEqual(main.classify_requirement("Older patterns are NOT RECOMMENDED."), "not_recommended")

def test_deprecated_feature_reports_its_migration_path(self) -> None:
        self.assertEqual(main.feature_state("logging", "2026-07-28"), "deprecated")
        self.assertIn("OpenTelemetry", main.migration_path("logging"))

def test_feature_is_active_before_its_own_deprecation_revision(self) -> None:
        self.assertEqual(main.feature_state("roots", "2025-11-25"), "active")
        self.assertEqual(main.feature_state("roots", "2026-07-28"), "deprecated")

def test_earliest_removal_is_computed_from_the_deprecation_window(self) -> None:
        self.assertEqual(main.earliest_removal("roots"), "2027-07-28")
        self.assertEqual(main.earliest_removal("dynamic-client-registration"), "2027-07-28")

def test_feature_that_follows_another_shares_its_earliest_removal(self) -> None:
        self.assertEqual(
            main.earliest_removal("include-context-this-server-all-servers"),
            main.earliest_removal("sampling"),
        )

def test_every_transcript_result_carries_a_result_type(self) -> None:
        for entry in main.transcript():
            message = entry.get("message", entry) if isinstance(entry, dict) and "violation" in entry else entry
            if isinstance(message, dict) and "result" in message:
                self.assertIn(message["result"]["resultType"], {"complete", "input_required"})

def test_one_protocol_turns_n_times_m_into_n_plus_m(self) -> None:
        self.assertEqual(main.integrations_without_protocol(4, 6), 24)
        self.assertEqual(main.integrations_with_protocol(4, 6), 10)

def test_one_client_discovers_two_unrelated_servers(self) -> None:
        self.assertEqual([tool["name"] for tool in self.weather.list_tools()], ["get_forecast"])
        self.assertEqual([tool["name"] for tool in self.tickets.list_tools()], ["count_open_tickets", "open_ticket"])

def test_every_result_carries_a_result_type(self) -> None:
        for message in main.transcript():
            if "result" in message:
                self.assertIn(message["result"]["resultType"], {"complete", "input_required"})

